import{_ as o,o as a,c as n,a2 as t}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"LINE","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/line.md","filePath":"ja/integrations/channels/line.md","lastUpdated":1792323081000}'),s={name:"ja/integrations/channels/line.md"};function l(r,e,i,h,g,c){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="line" tabindex="-1">LINE <a class="header-anchor" href="#line" aria-label="Permalink to &quot;LINE&quot;">​</a></h1><p>Memoh Bot を LINE 公式アカウントにつなぎます。ユーザーがそのアカウントを友だち追加すると、Bot と 1 対 1 でトークできます。</p><div class="warning custom-block"><p class="custom-block-title">使用制限</p><ul><li>1 対 1 のトークのみ対応します。グループや複数人トークルームのメッセージは無視されるため、Bot を LINE グループに招待しても機能しません。</li><li>出力はプレーンテキストのみで、Markdown はレンダリングされません。</li><li>送信できるメディアは PNG/JPEG 画像のみです。画像は公開の HTTPS でアクセスでき、かつ LINE のサイズ制限（元画像 10 MB、プレビュー画像 1 MB）に収まっている必要があります。画像以外の添付ファイルは送信できません。</li><li>受信した音声、動画、スタンプ、位置情報は処理されません。受信画像は LINE がホストしているものに限ります（アプリ内で直接写真を送った場合はこれに該当します）。</li><li>ストリーミング出力はなく、返信はメッセージ全体がまとめて届きます。長い返信は LINE の 5000 文字制限に合わせて複数のメッセージに分割されます。</li><li>返信は LINE の <strong>Push API</strong> 経由で送信されるため、LINE プランのプッシュメッセージ数の上限にカウントされます。</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><p>LINE は <strong>webhook</strong> でメッセージを Memoh に届け、送信画像も LINE のサーバー側から取得されるため、Memoh のデプロイには公開の HTTPS エンドポイントが必要です。次のいずれかで用意します。</p><ul><li><code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> に公開 HTTPS の origin を設定します（パス、ポート、プライベートアドレスは不可）。</li><li>または server deploy で Cloudflare Quick Tunnel profile を有効にすると、Memoh が自動的に公開アドレスを取得します。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-line-developers-console-で-messaging-api-channel-を作成する" tabindex="-1">1. LINE Developers Console で Messaging API channel を作成する <a class="header-anchor" href="#_1-line-developers-console-で-messaging-api-channel-を作成する" aria-label="Permalink to &quot;1. LINE Developers Console で Messaging API channel を作成する&quot;">​</a></h3><p>LINE Developers Console で次を行います。</p><ol><li><a href="https://developers.line.biz/console/" target="_blank" rel="noreferrer">LINE Developers Console</a> を開きます。</li><li>provider を作成（または選択）し、その下に <strong>Messaging API</strong> channel を作成します。channel は LINE 公式アカウントに関連付けられます。</li><li><strong>Basic settings</strong> で <strong>Channel secret</strong> をコピーします。</li><li><strong>Messaging API</strong> タブで <strong>Channel access token</strong>（長期）を発行してコピーします。</li></ol><blockquote><p>公式ドキュメント：<a href="https://developers.line.biz/en/docs/messaging-api/getting-started/" target="_blank" rel="noreferrer">Messaging API - Getting Started</a></p></blockquote><h3 id="_2-memoh-でチャネルを追加する" tabindex="-1">2. Memoh でチャネルを追加する <a class="header-anchor" href="#_2-memoh-でチャネルを追加する" aria-label="Permalink to &quot;2. Memoh でチャネルを追加する&quot;">​</a></h3><p>Memoh で次を行います。</p><ol><li>Bot の <strong>プラットフォーム</strong> タブを開きます。</li><li><strong>Add Channel</strong> をクリックし、<strong>LINE</strong> を選択します。</li><li><strong>Channel Secret</strong> と <strong>Channel Access Token</strong> を貼り付けます。</li><li><strong>Save</strong>（または <strong>Save and Enable</strong>）をクリックします。コールバック URL は保存して初めて生成されます。</li></ol><h3 id="_3-webhook-を登録する" tabindex="-1">3. webhook を登録する <a class="header-anchor" href="#_3-webhook-を登録する" aria-label="Permalink to &quot;3. webhook を登録する&quot;">​</a></h3><p>Memoh では、保存するとパネルに読み取り専用の <strong>WebHook Callback URL</strong> が次の形式で表示されます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://&lt;公開 base&gt;/channels/line/webhook/&lt;config_id&gt;</span></span></code></pre></div><p>登録方法は 2 通りあります。</p><ul><li><strong>Set in LINE</strong> をクリックします。Memoh が Messaging API 経由でアドレスを LINE の channel に直接書き込みます。未保存の変更があるとエラーになるため、保存してからクリックしてください。</li><li>または <strong>Copy</strong> をクリックし、LINE Developers Console の <strong>Messaging API → Webhook URL</strong> に手動で貼り付けます。</li></ul><p>最後に、LINE Developers Console でその channel の <strong>Use webhook</strong> がオンになっていることを確認します。</p><p>Memoh は受信 webhook の署名を <strong>Channel Secret</strong> で検証し、イベントは 24 時間にわたって重複排除されます。</p><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><strong>Channel Secret</strong></td><td>はい</td><td>Messaging API channel の <strong>Basic settings</strong> でコピーします。</td></tr><tr><td><strong>Channel Access Token</strong></td><td>はい</td><td><strong>Messaging API</strong> タブで発行する長期 token。</td></tr></tbody></table><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>LINE でその公式アカウントを友だち追加し、1 対 1 のトークで Bot に <code>/help</code> を送信します。Bot がコマンド一覧を返せば、チャネルは接続できています。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。認証情報を更新するときは、同じパネルで <strong>Channel Secret</strong> / <strong>Channel Access Token</strong> を更新して保存してください。</p><h2 id="faq" tabindex="-1">よくある質問 <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;よくある質問 {#faq}&quot;">​</a></h2><h3 id="no-public-base-url" tabindex="-1">パネルに公開 base URL を取得できないと表示される <a class="header-anchor" href="#no-public-base-url" aria-label="Permalink to &quot;パネルに公開 base URL を取得できないと表示される {#no-public-base-url}&quot;">​</a></h3><p>公開 HTTPS の origin がないと、webhook コールバック URL は生成できません。まず前提条件に従って <code>MEMOH_WEBHOOK_PUBLIC_BASE_URL</code> または Cloudflare Quick Tunnel を設定してください。</p>',30)])])}const b=o(s,[["render",l]]);export{p as __pageData,b as default};
